import {products,day,rating,confirmAdd,analogs,findProducts} from './core.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readStore(key,fallback){try{return JSON.parse(sessionStorage.getItem(key))??fallback;}catch{return fallback;}}
function saveStore(key,value){try{sessionStorage.setItem(key,JSON.stringify(value));}catch{}}
const state={lang:readStore('ekt-lang','ru'),category:'all',query:'',all:false,chatOpen:innerWidth>800,messages:[],cart:readStore('ekt-cart',{}),compare:[],pending:null,lastIds:[],voice:false,stops:0,tone:'simple',file:null};
if(!['ru','kk','en'].includes(state.lang))state.lang='ru';
state.cart=Object.fromEntries(Object.entries(state.cart).filter(([id,q])=>products.some(p=>p.id===id&&Number.isInteger(q)&&q>0&&q<=p.stock)));
const L=(ru,kk,en)=>({ru,kk,en})[state.lang];
const name=p=>p.name[state.lang];
const spec=p=>p.spec[state.lang];
const money=n=>new Intl.NumberFormat(state.lang==='en'?'en-US':'ru-RU').format(n)+' ₸';
const date=d=>new Date(d+'T12:00:00').toLocaleDateString({ru:'ru-RU',kk:'kk-KZ',en:'en-GB'}[state.lang],{day:'numeric',month:'short',year:'numeric'});
const unit=p=>p.unit==='m'?L('м','м','m'):L('шт.','дана','pcs');
const get=id=>products.find(p=>p.id===id);
const icon=(s)=>{const paths={search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',cart:'<path d="M3 4h2l2 11h11l3-8H6M9 20h.01M18 20h.01"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2" fill="white"/><circle cx="16" cy="12" r="2" fill="white"/><circle cx="8" cy="18" r="2" fill="white"/>',attach:'<path d="m9 13 6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l9-9M7 15l8-8"/>',sound:'<path d="M4 9h4l5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8M20 5a10 10 0 0 1 0 14"/>',compare:'<path d="M6 20V10M12 20V4M18 20V7"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[s]||''}</svg>`;};
function toast(text){const e=$('#toast');e.textContent=text;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',4500);}
const count=()=>Object.values(state.cart).reduce((a,b)=>a+b,0);
const stock=p=>p.stock?`${L('В наличии','Қоймада бар','In stock')} · ${p.stock} ${unit(p)}`:L('Нет в наличии','Қоймада жоқ','Out of stock');
function img(p,cls=''){return `<img class="${cls}" src="${p.image}" alt="${esc(L('Иллюстрация категории: ','Санат иллюстрациясы: ','Category illustration: ')+name(p))}" loading="lazy">`;}
function productCard(p,mini=false){const selected=state.compare.includes(p.id);if(mini)return `<div class="mini-card">${img(p)}<h4>${esc(name(p))}</h4><div class="mini-meta">${esc(spec(p))}</div><div class="mini-meta">${stock(p)}</div><b>${money(p.price)}${p.unit==='m'?' / '+unit(p):''}</b><button class="${p.stock?'primary':''}" data-action="${p.stock?'stage':'analogs'}" data-id="${p.id}">${p.stock?L('+ Добавить','+ Қосу','+ Add'):L('Показать аналоги','Баламаларын көру','Find alternatives')}</button><button class="text-button" data-action="detail" data-id="${p.id}">${L('Подробнее','Толығырақ','Details')}</button></div>`;
return `<article class="product"><div class="product-art" data-caption="${L('Фото категории','Санат фотосы','Category photo')}">${img(p)}<span class="stock ${p.stock?'':'sold'}">${stock(p)}</span><button class="compare-check ${selected?'selected':''}" data-action="compare-toggle" data-id="${p.id}" aria-pressed="${selected}" aria-label="${esc(L('Сравнить ','Салыстыру ','Compare ')+name(p))}">${selected?'✓':icon('compare')}</button></div><small>${p.id} · ${esc(p.brand.split(' · ')[0])}</small><h3>${esc(name(p))}</h3><p>${esc(spec(p))}</p><div class="product-bottom"><b>${money(p.price)}${p.unit==='m'?'<small> / '+unit(p)+'</small>':''}</b><button class="${p.stock?'primary':''}" data-action="${p.stock?'stage':'analogs'}" data-id="${p.id}">${p.stock?L('+ Добавить','+ Қосу','+ Add'):L('Аналоги','Баламалар','Alternatives')}</button></div><div class="product-tools"><button class="text-button" data-action="detail" data-id="${p.id}">${L('Подробнее','Толығырақ','Details')} ↗</button><button class="text-button" data-action="reviews" data-id="${p.id}">☆ ${rating(p.reviews).score?.toFixed(1)||'—'} <span class="muted">(${p.reviews.length})</span></button></div></article>`;}
function render(){document.documentElement.lang=state.lang;document.title=L('EKT · Ассистент по электротоварам','EKT · Электр тауарларының көмекшісі','EKT · Electrical product assistant');$('#app').innerHTML=`<header class="topbar"><a class="brand" href="#" aria-label="EKT">ekt<span>●</span></a><span class="brand-caption">${L('Электротехника<br>для ваших задач','Міндеттеріңізге арналған<br>электр тауарлары','Electrical products<br>for your projects')}</span><label class="search-box">${icon('search')}<input id="catalog-search" type="search" value="${esc(state.query)}" placeholder="${L('Поиск по названию или артикулу','Атауы не артикулы бойынша іздеу','Search by name or SKU')}" aria-label="${L('Поиск по каталогу','Каталогтан іздеу','Search catalog')}"></label><select id="lang" class="pill" aria-label="${L('Язык','Тіл','Language')}">${['ru','kk','en'].map(l=>`<option value="${l}" ${l===state.lang?'selected':''}>${{ru:'RU',kk:'ҚАЗ',en:'EN'}[l]}</option>`).join('')}</select><button class="primary" data-action="cart">${L('Корзина','Себет','Cart')} · ${count()}</button></header><main class="workspace ${state.chatOpen?'':'collapsed'}"><section class="catalog"><div class="eyebrow">${L('КАТАЛОГ / ЭЛЕКТРОТОВАРЫ','КАТАЛОГ / ЭЛЕКТР ТАУАРЛАРЫ','CATALOG / ELECTRICAL PRODUCTS')}</div><h1>${L('Подберём то, что нужно','Қажеттісін бірге таңдаймыз','Find the right fit')}<span class="accent">.</span></h1><p class="muted">${L('Характеристики, наличие и сравнение — в одном окне.','Сипаттамалар, қоймадағы қор және салыстыру — бір терезеде.','Specifications, availability and comparison in one place.')}</p><div class="tabs" role="group" aria-label="${L('Категории','Санаттар','Categories')}">${[['all',L('Все товары','Барлық тауарлар','All products')],['breaker',L('Автоматы','Автоматтар','Breakers')],['cable',L('Кабель','Кабель','Cables')],['home',L('Розетки и свет','Розетка және жарық','Sockets & lighting')]].map(([k,v])=>`<button data-action="category" data-id="${k}" class="${state.category===k?'active':''}" aria-pressed="${state.category===k}">${v}</button>`).join('')}</div><div class="catalog-meta"><b>${L('Подборка для вас','Сізге арналған таңдау','Selected for you')}</b><span>${L('8 товаров · демо-каталог','8 тауар · демо-каталог','8 products · demo catalog')}</span></div><div id="products" class="product-grid"></div><div id="more"></div><div class="demo-note"><span>${L('Демо HackAlem · цены, остатки и отзывы синтетические','HackAlem демо · бағалар, қор және пікірлер жасанды','HackAlem demo · synthetic prices, stock and reviews')}</span><div class="footer-links"><button class="text-button" data-supplier="all">ekt.kz · API ↗</button><button class="text-button" data-action="sources">${L('О данных и фото','Деректер мен фото','Data & photos')}</button><button class="text-button" data-action="demo">${L('Демо-сценарий','Демо-сценарий','Demo scenario')}</button></div></div></section>${state.chatOpen?`<aside class="assistant" aria-label="${L('ИИ-ассистент','ЖИ көмекшісі','AI assistant')}"><div class="assistant-header"><span class="assistant-icon">✦</span><div><b>EKT ${L('Ассистент','Көмекші','Assistant')}</b><div class="small">${L('Помогу разобраться с выбором','Таңдауға көмектесемін','Let’s find what you need')}</div></div><button class="icon-button" data-action="settings" aria-label="${L('Настройки','Баптаулар','Settings')}">${icon('settings')}</button><button class="icon-button" data-action="chat-close" aria-label="${L('Свернуть чат','Чатты жию','Minimize chat')}">${icon('close')}</button></div><div id="chat-body" class="chat-body" role="log" aria-live="polite"></div><div id="attachment"></div><form id="chat-form" class="composer"><button class="icon-button" type="button" data-action="attach" aria-label="${L('Прикрепить файл','Файл тіркеу','Attach a file')}">${icon('attach')}</button><input id="chat-input" maxlength="2000" autocomplete="off" placeholder="${L('Спросите о товаре…','Тауар туралы сұраңыз…','Ask about a product…')}" aria-label="${L('Сообщение','Хабарлама','Message')}"><button class="primary" type="submit" aria-label="${L('Отправить','Жіберу','Send')}">↑</button></form><input id="file-input" type="file" accept=".xlsx,.xls,.docx,.doc,.pdf,.jpg,.jpeg" hidden><div class="assistant-foot">${L('Демо · сценарные ответы · файлы не отправляются','Демо · сценарийлік жауаптар · файлдар жіберілмейді','Demo · scripted replies · files stay on this device')}</div></aside>`:''}</main>${!state.chatOpen?`<button class="primary assistant-launcher ${state.compare.length?'with-compare':''}" data-action="chat-open"><span>✦</span> EKT ${L('Ассистент','Көмекші','Assistant')}</button>`:''}${state.compare.length?`<div class="comparison-bar"><span>${L('В сравнении','Салыстыруда','Comparing')}: ${state.compare.length}</span><button data-action="comparison">${L('Сравнить','Салыстыру','Compare')} ↗</button><button class="icon-button" style="color:white" data-action="compare-clear" aria-label="${L('Очистить сравнение','Салыстыруды тазарту','Clear comparison')}">×</button></div>`:''}`;renderProducts();renderChat();}
function renderProducts(){let list=state.query?findProducts(state.query,products):products;list=list.filter(p=>state.category==='all'||p.category===state.category||(state.category==='home'&&['socket','light'].includes(p.category)));const visible=state.all?list:list.slice(0,4);$('#products').innerHTML=visible.length?visible.map(p=>productCard(p)).join(''):`<div class="empty-state">${L('Ничего не найдено. Попробуйте C16 или DEMO-101.','Ештеңе табылмады. C16 немесе DEMO-101 деп іздеңіз.','No matches. Try C16 or DEMO-101.')}</div>`;$('#more').innerHTML=list.length>4?`<button class="more" data-action="more">${state.all?L('Показать меньше','Азырақ көрсету','Show less'):L('Показать ещё','Тағы көрсету','Show more')} ${!state.all?'('+ (list.length-4)+')':''}</button>`:'';}
function greeting(){return `<div class="chat-date">${L('Ваш помощник по электротехнике','Электр тауарлары бойынша көмекші','Your electrical product guide')}</div><div class="greeting"><span class="star">✦</span><h2>${L('Хороший выбор<br>начинается с вопроса','Дұрыс таңдау<br>сұрақтан басталады','A good choice<br>starts with a question')}</h2><p>${L('Расскажите, что ищете. Сравним варианты, проверим характеристики и соберём корзину.','Не іздеп жатқаныңызды айтыңыз. Нұсқаларды салыстырып, сипаттамаларын тексеріп, себетті жинаймыз.','Tell me what you’re looking for. We’ll compare options, check specifications and put your cart together.')}</p></div><div class="suggestions">${[L('Подобрать автомат C16','C16 автоматын таңдау','Find a C16 breaker'),L('Нужен аналог DEMO-103','DEMO-103 баламасы керек','Alternative to DEMO-103'),L('Что лучше купить сейчас?','Қазір қайсысын алған дұрыс?','What is the best choice now?')].map(q=>`<button data-action="suggest" data-text="${esc(q)}">${q}<span>↗</span></button>`).join('')}</div><p class="privacy">${L('В корзину — только с вашего подтверждения','Себетке тек сіздің растауыңызбен қосылады','Cart changes always need your confirmation')}</p>`;}
function renderChat(){if(!$('#chat-body'))return;$('#chat-body').innerHTML=state.messages.length?state.messages.map((m,i)=>`<div class="message ${m.role}">${m.role==='bot'?`<div class="bot-label">✦ EKT ${L('Ассистент','Көмекші','Assistant')} <button class="icon-button" data-action="speak" data-index="${i}" aria-label="${L('Озвучить или остановить','Оқу не тоқтату','Read aloud or stop')}">${icon('sound')}</button></div>`:''}<p>${esc(m.text)}</p>${m.ids?.length?`<div class="response-grid">${m.ids.map(get).filter(Boolean).map(p=>productCard(p,true)).join('')}</div>`:''}${m.cart?`<a class="primary" style="display:inline-block;padding:9px 12px;border-radius:9px" href="#cart">${L('Перейти в корзину','Себетке өту','Go to cart')} ↗</a>`:''}</div>`).join(''):greeting();if(state.pending){const p=get(state.pending.id);$('#chat-body').insertAdjacentHTML('beforeend',`<div class="confirmation"><b>${L('Подтвердите добавление','Қосуды растаңыз','Confirm addition')}</b><p class="selected-name">${esc(name(p))}</p><label>${L('Количество','Саны','Quantity')} (${unit(p)}) <input id="pending-qty" type="number" min="1" max="${p.stock-(state.cart[p.id]||0)}" step="1" value="${state.pending.qty}" aria-label="${L('Количество для добавления','Қосылатын саны','Quantity to add')}"></label><div class="small">${money(p.price)} × <span id="qty-summary">${state.pending.qty}</span> = <b id="pending-total">${money(p.price*state.pending.qty)}</b></div><div class="actions"><button class="primary" data-action="confirm">${L('Да, добавить','Иә, қосу','Yes, add')}</button><button data-action="cancel">${L('Отмена','Бас тарту','Cancel')}</button></div></div>`);}$('#chat-body').scrollTop=$('#chat-body').scrollHeight;renderAttachment();}
function renderAttachment(){if(!$('#attachment'))return;$('#attachment').innerHTML=state.file?`<div class="attachment"><span>${esc(state.file.name)} · ${Math.ceil(state.file.size/1024)} KB</span><button class="icon-button" data-action="file-remove" aria-label="${L('Убрать файл','Файлды жою','Remove file')}">×</button></div>`:'';}
function say(text,ids=[],cart=false){state.messages.push({role:'bot',text,ids,cart});if(ids.length)state.lastIds=ids;renderChat();if(state.voice)speak(text);}
function ensureChat(){if(!state.chatOpen){state.chatOpen=true;render();}}
function stage(id,qty=1){const p=get(id);if(!p)throw Error('unknown_product');if(!Number.isInteger(qty)||qty<1||qty+(state.cart[id]||0)>p.stock){toast(L('Проверьте количество и остаток.','Саны мен қорды тексеріңіз.','Check quantity and available stock.'));return false;}closeModal();ensureChat();state.pending={id,qty,expires:Date.now()+300000};renderChat();return true;}
function confirm(){if(!state.pending)return;const pending=state.pending;const p=get(pending.id);const input=$('#pending-qty');const q=input?Number(input.value):pending.qty;if(Date.now()>pending.expires){state.pending=null;renderChat();toast(L('Подтверждение истекло. Выберите товар заново.','Растау мерзімі өтті. Тауарды қайта таңдаңыз.','Confirmation expired. Select the product again.'));return;}try{state.cart=confirmAdd(state.cart,p,q,true);saveStore('ekt-cart',state.cart);state.pending=null;state.messages.push({role:'bot',text:L(`Добавлено: ${name(p)}, ${q} ${unit(p)}. Итого по позиции: ${money(p.price*state.cart[p.id])}.`,`Қосылды: ${name(p)}, ${q} ${unit(p)}. Позиция сомасы: ${money(p.price*state.cart[p.id])}.`,`Added: ${name(p)}, ${q} ${unit(p)}. Item subtotal: ${money(p.price*state.cart[p.id])}.`),cart:true});render();}catch{toast(L('Количество должно быть целым и не превышать остаток с учётом корзины.','Саны бүтін болып, себеттегі санымен бірге қордан аспауы тиіс.','Quantity must be a whole number and fit the remaining stock, including your cart.'));}}
function recommend(list){const available=list.filter(p=>p.stock>0);if(!available.length)return L('Сейчас доступных вариантов нет. Дату поставки должен подтвердить поставщик.','Қазір қолжетімді нұсқа жоқ. Жеткізу күнін жеткізуші растауы керек.','No available options. The supplier needs to confirm the arrival date.');if(new Set(available.map(p=>p.compat)).size>1)return L('У этих товаров разные задачи или характеристики. Выберите совместимые позиции: например два автомата C16. Низкая цена сама по себе не делает товар подходящим.','Бұл тауарлардың міндеті не сипаттамалары әртүрлі. Екі C16 автоматы сияқты үйлесімді тауарларды таңдаңыз. Арзан баға жарамдылықты білдірмейді.','These products have different purposes or specifications. Select compatible items, such as two C16 breakers. A lower price alone does not make an item suitable.');const best=[...available].sort((a,b)=>a.price-b.price)[0];const diff=best.price-best.history[0];return L(`По текущим демо-данным выгоднее ${name(best)} за ${money(best.price)}: самая низкая цена среди доступных совместимых вариантов. Ключевые параметры: ${spec(best)}. Изменение к началу истории: ${diff>0?'+':''}${money(diff)}. Это не прогноз цены и не оценка безопасности. Перед заменой проверьте полные характеристики и сертификат.`,`Қазіргі демо-деректер бойынша ${money(best.price)} тұратын ${name(best)} тиімді: қолжетімді үйлесімді нұсқалар ішіндегі ең төмен баға. Негізгі параметрлер: ${spec(best)}. Баға болжамы немесе қауіпсіздік бағасы емес. Ауыстыру алдында толық сипаттамалар мен сертификатты тексеріңіз.`,`Based on demo data, ${name(best)} at ${money(best.price)} is the lowest-priced available compatible option. Key specifications: ${spec(best)}. Change since the start of the sample: ${diff>0?'+':''}${money(diff)}. This is not a price forecast or a safety assessment. Check full specifications and certification before substitution.`);}
function showAnalogs(id){const p=get(id);closeModal();ensureChat();const list=analogs(p,products);state.pending=null;const arrival=p.arrival?L(`Плановое поступление в демо: ${date(p.arrival)}; дата не гарантирована.`,`Демодағы жоспарлы келуі: ${date(p.arrival)}; күн кепілдендірілмеген.`,`Planned demo arrival: ${date(p.arrival)}; the date is not guaranteed.`):L('Дата поступления не подтверждена.','Келу күні расталмаған.','Arrival date is unconfirmed.');say(`${name(p)}: ${stock(p)}. ${!p.stock?arrival:''}\n`+(list.length?L(`Подойдут для сравнения: совпадают ключевые параметры (${spec(p)}). Совместимость с вашей установкой нужно проверить по полным характеристикам.`,`Салыстыруға болады: негізгі параметрлер сәйкес (${spec(p)}). Қондырғыңызбен үйлесімділігін толық сипаттамалар арқылы тексеру керек.`,`These alternatives share the key specifications (${spec(p)}). Verify suitability for your installation using the full specifications.`):L('Подтверждённых аналогов в выборке нет.','Іріктемеде расталған балама жоқ.','No verified alternatives in this sample.')),list.map(p=>p.id));}
function send(text){text=text.trim();if(!text&&!state.file)return;ensureChat();state.messages.push({role:'user',text:text||L('Вложение','Тіркеме','Attachment')});if(state.file){const file=state.file;state.file=null;say(L(`Файл «${file.name}» выбран локально. В этом frontend-демо распознавание Excel, Word, PDF и фото ещё не подключено: содержимое не прочитано и не отправлено. Введите артикул или характеристики текстом.`,`«${file.name}» файлы жергілікті таңдалды. Бұл frontend-демода Excel, Word, PDF және фото тану қосылмаған: мазмұны оқылмады және жіберілмеді. Артикулды немесе сипаттаманы мәтінмен енгізіңіз.`,`“${file.name}” is selected locally. Excel, Word, PDF and photo extraction is not connected in this frontend demo. Contents have not been read or sent. Enter the SKU or specifications as text.`));return;}if(/^(да,? добавь|да,? добавить|иә,? қос|yes,? add)[.!]?$/i.test(text)){if(state.pending)confirm();else say(L('Сначала выберите товар и количество.','Алдымен тауар мен санын таңдаңыз.','Select a product and quantity first.'));return;}state.pending=null;const q=text.toLowerCase();let matches=findProducts(text,products);const explicit=text.match(/demo[- ]?\d{3}/i)?.[0].toUpperCase().replace(' ','-');const context=explicit?get(explicit):state.lastIds.length===1?get(state.lastIds[0]):null;
if(/аналог|балама|alternativ/.test(q)){const p=context||get('DEMO-103');showAnalogs(p.id);return;}
if(/достав|оплат|покупк|услов|жеткіз|төлем|шарт|shipping|payment|delivery|minimum/.test(q)){say(L('Демо-условия: минимальная партия — 1 шт., кабель — от 1 м. Предусмотрены самовывоз и доставка; стоимость, срок и способ оплаты уточняет менеджер. Это пример сценария, а не действующие условия ekt.kz. Платёжные данные в чат не вводите.','Демо-шарттар: ең аз тапсырыс — 1 дана, кабель — 1 метрден. Алып кету және жеткізу қарастырылған; құны, мерзімі мен төлем әдісін менеджер нақтылайды. Бұл ekt.kz нақты шарттары емес, сценарий үлгісі. Төлем деректерін чатқа енгізбеңіз.','Demo terms: minimum quantity is 1 piece, or 1 metre for cable. Pickup and delivery are available in the scenario; a manager confirms cost, timing and payment methods. These are sample terms, not actual ekt.kz policy. Do not enter payment details in chat.'));return;}
if(/лучше|выгод|тиімді|дұрыс|best|recommend/.test(q)){const list=state.compare.length?state.compare.map(get):products.filter(p=>p.compat==='mcb-1p-c16-6ka');say(recommend(list),list.filter(p=>p.stock).slice(0,2).map(p=>p.id));return;}
if(/сравн|салыстыр|compare/.test(q)){const list=matches.length?matches:state.lastIds.map(get);state.compare=list.slice(0,3).map(p=>p.id);render();showComparison();return;}
if(/отзыв|качеств|пікір|сапа|review|quality/.test(q)){const p=context||get('DEMO-101');const r=rating(p.reviews);say(L(`${name(p)}: оценка отзывов ${r.score?.toFixed(1)||'—'}/5 (${r.count}). ${r.period==='today'?'Есть отзывы за сегодня.':'Сегодня отзывов нет: использована история за последние 30 дней.'} Это мнение покупателей, а не техническая оценка качества или безопасности. Все исходные отзывы в демо синтетические.`,`${name(p)}: пікір бағасы ${r.score?.toFixed(1)||'—'}/5 (${r.count}). ${r.period==='today'?'Бүгінгі пікірлер бар.':'Бүгін пікір жоқ: соңғы 30 күн тарихы қолданылды.'} Бұл сатып алушылар пікірі, техникалық сапа немесе қауіпсіздік бағасы емес. Бастапқы пікірлер жасанды.`,`${name(p)}: review score ${r.score?.toFixed(1)||'—'}/5 (${r.count}). ${r.period==='today'?'Reviews are available today.':'No reviews today; using the last 30 days.'} This reflects buyer opinion, not technical quality or safety. All seeded reviews are synthetic.`),[p.id]);return;}
if(/сертифик|certificate/.test(q)){const p=context||get('DEMO-101');say(L(`${name(p)}: сертификат в демо-каталоге отсутствует. Я не могу подтвердить соответствие; запросите документ у менеджера.`,`${name(p)}: демо-каталогта сертификат жоқ. Сәйкестігін растай алмаймын; құжатты менеджерден сұраңыз.`,`${name(p)}: no certificate is provided in this demo catalog. I cannot confirm compliance; request the document from a manager.`),[p.id]);return;}
if(/добав|қос|\badd\b/.test(q)){const p=context||matches[0];if(p){const quantity=Number(q.match(/(?:количеств\w*|quantity)\s*(\d+)/)?.[1]||q.match(/(\d+)\s*(?:шт|дана|pcs|pieces|метр|м\b)/)?.[1]||1);if(!p.stock){showAnalogs(p.id);return;}if(stage(p.id,quantity))return;}else say(L('Укажите артикул и количество, например «добавь DEMO-101 2 шт».','Артикул мен санын көрсетіңіз, мысалы «DEMO-101 2 дана қос».','Specify SKU and quantity, for example “add DEMO-101 2 pcs”.'));return;}
if(/корзин|себет|cart/.test(q)){say(L('Ваша демо-корзина доступна по ссылке.','Демо-себетіңіз сілтемеде қолжетімді.','Your demo cart is available at this link.'),[],true);return;}
if(context&&(/налич|поступ|қойма|кел|stock|arrival/.test(q)||matches.length===1)){say(`${name(context)}: ${stock(context)}. ${money(context.price)} / ${unit(context)}.\n${spec(context)}.\n`+(context.stock?L('Остатки по складам: ','Қоймалардағы қор: ','Warehouse stock: ')+context.warehouses.map(([w,n])=>`${w} — ${n}`).join(', '):context.arrival?L('Плановое поступление (демо): ','Жоспарлы келуі (демо): ','Planned arrival (demo): ')+date(context.arrival)+'. '+L('Срок не гарантирован.','Мерзім кепілдендірілмеген.','Date is not guaranteed.'):L('Дата поступления не подтверждена.','Келу күні расталмаған.','Arrival date is unconfirmed.')),[context.id]);if(!context.stock){const al=analogs(context,products);if(al.length)say(L('Также есть варианты с теми же ключевыми параметрами.','Негізгі параметрлері сәйкес нұсқалар да бар.','These options share the same key specifications.'),al.map(p=>p.id));}return;}
if(matches.length){say(L(`Нашёл ${matches.length} варианта в демо-каталоге. ${state.tone==='technical'?'Проверьте номинальный ток, число полюсов, характеристику срабатывания и отключающую способность.':'Нажмите «Подробнее», чтобы увидеть состав, происхождение, отзывы и динамику цены.'}`,`Демо-каталогтан ${matches.length} нұсқа табылды. Құрамы, шыққан жері, пікірлер мен баға өзгерісін көру үшін «Толығырақ» басыңыз.`,`Found ${matches.length} options in the demo catalog. ${state.tone==='technical'?'Check rated current, pole count, trip curve and breaking capacity.':'Open Details for materials, origin, reviews and price history.'}`),matches.slice(0,4).map(p=>p.id));return;}
say(L('Помогу с артикулом, наличием, аналогами и сравнением. Например: «автомат C16 до 3000», «DEMO-103», «условия доставки». Для подбора под нагрузку нужны параметры сети и оборудования; номинал нельзя выбирать только по цене.','Артикул, қор, балама және салыстыру бойынша көмектесемін. Мысалы: «C16», «DEMO-103», «жеткізу шарттары». Жүктемеге сай таңдау үшін желі мен жабдық параметрлері қажет. Номиналды тек баға бойынша таңдауға болмайды.','I can help with SKUs, availability, alternatives and comparison. Try “C16 under 3000”, “DEMO-103” or “delivery terms”. Load-based selection needs circuit and equipment details; do not choose a rating solely by price.'));}
function modal(title,html){closeModal();const dialog=document.createElement('dialog');dialog.id='modal';dialog.setAttribute('aria-labelledby','modal-title');dialog.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="modal-close" aria-label="${L('Закрыть','Жабу','Close')}">${icon('close')}</button></div><div class="modal-body">${html}</div>`;document.body.append(dialog);dialog.addEventListener('close',()=>{if(!dialog.isConnected)return;if(location.hash==='#cart')history.replaceState(null,'',location.pathname);dialog.remove();});dialog.showModal();}
function closeModal(){document.querySelectorAll('dialog').forEach(d=>{d.close();d.remove();});if(location.hash==='#cart')history.replaceState(null,'',location.pathname);}
const row=(label,value)=>`<div class="spec-row"><span>${label}</span><b>${esc(value)}</b></div>`;
function showDetail(id,reviewsFocus=false){const p=get(id);const r=rating(p.reviews);const hist=p.history;const low=Math.min(...hist),high=Math.max(...hist),range=high-low||1;const pts=hist.map((n,i)=>`${12+i*238},${96-(n-low)/range*70}`).join(' ');modal(name(p),`<div class="detail-top">${img(p,'detail-image')}<div><span class="badge">${p.id} · DEMO</span><h3>${esc(name(p))}</h3><p>${esc(spec(p))}</p><span class="stock" style="position:static">${stock(p)}</span><div class="price-large">${money(p.price)} <small class="muted">/ ${unit(p)}</small></div><button class="primary" data-action="${p.stock?'stage':'analogs'}" data-id="${p.id}">${p.stock?L('Добавить в корзину','Себетке қосу','Add to cart'):L('Показать аналоги','Баламаларын көру','Find alternatives')}</button></div></div><p class="small">${L('Фото иллюстрирует категорию, а не конкретную модель. Все сведения о товаре демонстрационные.','Фото нақты модельді емес, санатты көрсетеді. Тауар туралы барлық деректер демонстрациялық.','Photo illustrates the category, not the exact model. All product details are demo data.')}</p><h3>${L('О товаре','Тауар туралы','Product information')}</h3><div class="specs">${row(L('Материалы / состав','Материалдар / құрамы','Materials'),p.material[state.lang])}${row(L('Произведено','Шыққан жері','Origin'),p.origin[state.lang])}${row(L('Характеристики','Сипаттамалар','Specifications'),spec(p))}${row(L('Дата данных','Деректер күні','Data date'),date(p.updatedAt))}${row(L('Дата изготовления','Өндірілген күні','Manufactured'),L('Нет данных','Дерек жоқ','Not provided'))}${row(L('Сертификат','Сертификат','Certificate'),L('Не предоставлен','Берілмеген','Not provided'))}</div><p class="muted">${p.stock?p.warehouses.map(([w,n])=>`${w}: ${n} ${unit(p)}`).join(' · '):p.arrival?L('Плановое поступление (демо): ','Жоспарлы келуі (демо): ','Planned arrival (demo): ')+date(p.arrival)+'. '+L('Дата не гарантирована.','Күн кепілдендірілмеген.','Not guaranteed.'):L('Дата поступления не подтверждена.','Келу күні расталмаған.','Arrival date is unconfirmed.')}</p><h3>${L('Динамика цены','Баға өзгерісі','Price history')}</h3><svg class="price-chart" viewBox="0 0 500 120" role="img" aria-label="${esc(L('Демо-цены: ','Демо-бағалар: ','Demo prices: ')+hist.map(money).join(', '))}"><polyline points="${pts}" fill="none" stroke="#8451D7" stroke-width="3"/>${hist.map((n,i)=>`<circle cx="${12+i*238}" cy="${96-(n-low)/range*70}" r="4" fill="#8451D7"/><text x="${12+i*238}" y="${80-(n-low)/range*70}" text-anchor="${i===0?'start':i===2?'end':'middle'}" fill="#6133a9" font-size="13">${n} ₸</text>`).join('')}</svg><div class="chart-labels">${[-30,-14,0].map(o=>`<span>${date(day(o))}</span>`).join('')}</div><p class="small">${L('Синтетическая история; не прогноз будущих цен.','Жасанды тарих; болашақ баға болжамы емес.','Synthetic history; not a forecast of future prices.')}</p><h3 id="reviews-heading">${L('Что думают покупатели','Сатып алушылар пікірі','Buyer reviews')} <span class="stars">☆ ${r.score?.toFixed(1)||'—'}</span></h3><div class="muted-box">${r.count?L(`${r.count} отзыва. ${r.period==='today'?'Оценка по сегодняшним отзывам.':'Сегодня отзывов нет: среднее за последние 30 дней.'} Последний отзыв: ${date(r.last)}.`,`${r.count} пікір. ${r.period==='today'?'Бүгінгі пікірлер бағасы.':'Бүгін пікір жоқ: соңғы 30 күннің орташа бағасы.'} Соңғы пікір: ${date(r.last)}.`,`${r.count} reviews. ${r.period==='today'?'Score uses today’s reviews.':'No reviews today: average of the last 30 days.'} Latest review: ${date(r.last)}.`):L('Недостаточно данных для оценки.','Бағалау үшін дерек жеткіліксіз.','Not enough data for a score.')} ${L('Отзывы не подтверждают техническую безопасность.','Пікірлер техникалық қауіпсіздікті растамайды.','Reviews do not establish technical safety.')}</div>${p.reviews.map(rv=>`<div class="review"><div class="review-head"><b>${esc(rv.author)} <span class="stars">${'★'.repeat(rv.score)}</span></b><time>${date(rv.date)}</time></div><p class="review-text">${esc(typeof rv.text==='string'?rv.text:rv.text[state.lang])}</p><span class="small">${rv.synthetic?L('Пример отзыва · синтетические данные','Пікір үлгісі · жасанды деректер','Sample review · synthetic data'):L('Ваш отзыв · только в этой сессии · покупка не проверена','Сіздің пікіріңіз · тек осы сессияда · сатып алу тексерілмеген','Your review · this session only · purchase unverified')}</span></div>`).join('')}<form id="review-form" class="review-form" data-id="${p.id}"><h3>${L('Оставить отзыв','Пікір қалдыру','Write a review')}</h3><label>${L('Оценка','Баға','Rating')}<select name="score" aria-label="${L('Оценка отзыва','Пікір бағасы','Review rating')}">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} / 5</option>`).join('')}</select></label><textarea name="review" minlength="5" maxlength="1000" required placeholder="${L('Что понравилось? Не указывайте личные данные.','Не ұнады? Жеке деректерді енгізбеңіз.','What worked well? Do not include personal information.')}" aria-label="${L('Текст отзыва','Пікір мәтіні','Review text')}"></textarea><p class="small">${L('Отзыв останется только в текущей сессии и исчезнет после перезагрузки.','Пікір тек осы сессияда қалады және бетті жаңартқанда жойылады.','Your review stays in this session and is cleared on reload.')}</p><button class="primary" type="submit">${L('Добавить отзыв в демо','Демоға пікір қосу','Add demo review')}</button></form>`);if(reviewsFocus)$('#reviews-heading').scrollIntoView({block:'start'});}
function showComparison(){if(!state.compare.length){toast(L('Выберите товары значком сравнения.','Салыстыру белгісімен тауарларды таңдаңыз.','Select products using the comparison icon.'));return;}const list=state.compare.map(get);const fields=[[L('Цена','Баға','Price'),p=>money(p.price)],[L('Характеристики','Сипаттамалар','Specifications'),spec],[L('Наличие','Қор','Availability'),stock],[L('Материалы','Материалдар','Materials'),p=>p.material[state.lang]],[L('Происхождение','Шыққан жері','Origin'),p=>p.origin[state.lang]],[L('Отзывы за 30 дней / сегодня','30 күн / бүгінгі пікірлер','Reviews: last 30 days / today'),p=>{const r=rating(p.reviews);return`${r.score?.toFixed(1)||'—'} / 5 (${r.count})`;}],[L('Изменение за 30 дней','30 күндегі өзгеріс','30-day change'),p=>`${((p.price/p.history[0]-1)*100).toFixed(1)}%`],[L('Сертификат','Сертификат','Certificate'),()=>L('Не предоставлен','Берілмеген','Not provided')]];modal(L('Сравнение товаров','Тауарларды салыстыру','Product comparison'),`<p class="muted">${L('Сравнивайте характеристики, не закрывая чат. Данные демонстрационные.','Чатты жаппай сипаттамаларды салыстырыңыз. Деректер демонстрациялық.','Compare specifications without leaving the chat. Demo data.')}</p><div class="table-scroll"><table><thead><tr><th>${L('Параметр','Параметр','Parameter')}</th>${list.map(p=>`<th>${esc(name(p))}<div class="small">${p.id}</div></th>`).join('')}</tr></thead><tbody>${fields.map(([label,f])=>`<tr><td>${label}</td>${list.map(p=>`<td>${esc(f(p))}</td>`).join('')}</tr>`).join('')}<tr><td></td>${list.map(p=>`<td><button class="primary" data-action="${p.stock?'stage':'analogs'}" data-id="${p.id}">${p.stock?L('Добавить','Қосу','Add'):L('Аналоги','Баламалар','Alternatives')}</button></td>`).join('')}</tr></tbody></table></div><div style="margin-top:22px"><button class="primary" data-action="recommend-compare">✦ ${L('Что лучше сейчас?','Қазір қайсысы тиімді?','What is best now?')}</button><div id="compare-answer" aria-live="polite"></div></div>`);}
function showCart(){modal(L('Ваша корзина','Сіздің себетіңіз','Your cart'),Object.keys(state.cart).length?`${Object.entries(state.cart).map(([id,q])=>{const p=get(id);const r=rating(p.reviews);return `<div class="cart-row">${img(p)}<div><h3>${esc(name(p))}</h3><p>${p.id} · ${money(p.price)} × ${q} ${unit(p)}</p><p>☆ ${r.score?.toFixed(1)||'—'} / 5 · ${L('по отзывам','пікір бойынша','review score')}, ${r.count} · ${r.period==='today'?L('сегодня','бүгін','today'):L('30 дней','30 күн','30 days')}</p><button class="text-button" data-action="detail" data-id="${id}">${L('Качество и источник оценки','Сапа және баға дереккөзі','Quality and score source')}</button></div><div><b>${money(p.price*q)}</b><div style="margin-top:8px"><button class="text-button" data-action="cart-edit" data-id="${id}">${L('Изменить','Өзгерту','Edit')}</button></div></div></div>`;}).join('')}<div class="cart-total"><span>${L('Итого','Барлығы','Total')}</span><b>${money(Object.entries(state.cart).reduce((a,[id,q])=>a+get(id).price*q,0))}</b></div><div class="notice">${L('Это демо-корзина. Заказ не оформляется и в ekt.kz не передаётся. Для реальной покупки требуется подключить API корзины магазина и заново проверить цены и остатки.','Бұл демо-себет. Тапсырыс рәсімделмейді және ekt.kz сайтына жіберілмейді. Нақты сатып алу үшін дүкеннің себет API-ін қосып, баға мен қорды қайта тексеру қажет.','This is a demo cart. No order is placed or sent to ekt.kz. A real purchase requires the store cart API and a fresh price and stock check.')}</div><div class="inline-actions" style="margin-top:18px"><button class="primary" data-action="checkout-demo">${L('Проверить перед оформлением','Рәсімдеу алдында тексеру','Review before checkout')}</button><button data-action="modal-close">${L('Продолжить выбор','Таңдауды жалғастыру','Continue browsing')}</button></div>`:`<div class="empty-state"><span class="star">✦</span><h3>${L('Корзина пока пуста','Себет әзірше бос','Your cart is empty')}</h3><p>${L('Выберите товар и подтвердите добавление.','Тауарды таңдап, қосуды растаңыз.','Select a product and confirm the addition.')}</p><button class="primary" data-action="modal-close">${L('К товарам','Тауарларға өту','Browse products')}</button></div>`);}
function editCart(id){const p=get(id);modal(L('Изменение корзины','Себетті өзгерту','Edit cart'),`<h3>${esc(name(p))}</h3><p>${L('Изменения применятся только после подтверждения. Ноль удалит позицию.','Өзгеріс растаудан кейін ғана қолданылады. Нөл позицияны жояды.','Changes apply only after confirmation. Zero removes this item.')}</p><form id="cart-edit-form" data-id="${id}"><label class="setting">${L('Количество','Саны','Quantity')}<input type="number" name="quantity" min="0" max="${p.stock}" step="1" value="${state.cart[id]}" required></label><button type="submit" class="primary">${L('Подтвердить изменение','Өзгерісті растау','Confirm change')}</button> <button type="button" data-action="cart">${L('Отмена','Бас тарту','Cancel')}</button></form>`);}
function showSettings(){modal(L('Настройки ассистента','Көмекші баптаулары','Assistant settings'),`<label class="setting"><span>${L('Язык общения','Сөйлесу тілі','Language')}</span><select id="settings-lang">${[['ru','Русский'],['kk','Қазақша'],['en','English']].map(([k,v])=>`<option value="${k}" ${state.lang===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="setting"><span>${L('Стиль объяснения','Түсіндіру стилі','Explanation style')}</span><select id="tone"><option value="simple" ${state.tone==='simple'?'selected':''}>${L('Простыми словами','Қарапайым тілмен','Plain language')}</option><option value="technical" ${state.tone==='technical'?'selected':''}>${L('Технически подробно','Техникалық толық','Technical detail')}</option></select></label><label class="setting"><span>${L('Озвучивать ответы','Жауаптарды дыбыстау','Read replies aloud')}<small>${L('Только после вашего вопроса. После трёх остановок озвучивание отключится.','Тек сұрағыңыздан кейін. Үш рет тоқтатқан соң дыбыстау өшеді.','Only after your question. Three interruptions turn it off.')}</small></span><input id="voice-toggle" type="checkbox" ${state.voice?'checked':''}></label><label class="setting"><span>${L('Голос','Дауыс','Voice')}<small>${L('Доступны только локальные голоса браузера для выбранного языка. Качество зависит от устройства.','Таңдалған тіл үшін браузердің жергілікті дауыстары ғана қолжетімді. Сапасы құрылғыға байланысты.','Only device-local voices for the selected language. Quality depends on your device.')}</small></span><select id="voice-select">${localVoices().length?localVoices().map(v=>`<option value="${esc(v.voiceURI)}" ${state.voiceURI===v.voiceURI?'selected':''}>${esc(v.name)}</option>`).join(''):`<option>${L('Нет доступного голоса','Қолжетімді дауыс жоқ','No available voice')}</option>`}</select></label><button data-action="voice-preview">${L('Послушать голос','Дауысты тыңдау','Preview voice')}</button> <button data-action="voice-stop">${L('Остановить','Тоқтату','Stop')}</button><hr class="section-rule"><div class="muted-box">${L('Переписка, вложения и отзывы не отправляются на сервер. Демо-корзина и язык сохраняются в этой вкладке. После перезагрузки чат и отзывы очищаются.','Хаттар, тіркемелер мен пікірлер серверге жіберілмейді. Демо-себет пен тіл осы қойындыда сақталады. Жаңартқанда чат пен пікірлер тазарады.','Messages, attachments and reviews are not sent to a server. Demo cart and language are stored in this tab. Chat and reviews reset on reload.')}</div>`);}
function localVoices(){return ('speechSynthesis'in window?speechSynthesis.getVoices():[]).filter(v=>v.localService&&v.lang.toLowerCase().startsWith(state.lang==='kk'?'kk':state.lang));}
function speak(text){if(!('speechSynthesis'in window)){toast(L('Озвучивание не поддерживается.','Дыбыстау қолдау таппайды.','Speech is not supported.'));return;}if(speechSynthesis.speaking){stopVoice();return;}const voices=localVoices();const v=voices.find(v=>v.voiceURI===state.voiceURI)||voices[0];if(!v){state.voice=false;toast(L('Локальный голос для этого языка недоступен.','Бұл тіл үшін жергілікті дауыс жоқ.','No local voice is available for this language.'));return;}const u=new SpeechSynthesisUtterance(text);u.voice=v;u.lang=v.lang;u.rate=.94;u.pitch=1;u.onerror=()=>{state.voice=false;};speechSynthesis.speak(u);}
function stopVoice(){if('speechSynthesis'in window){const active=speechSynthesis.speaking;speechSynthesis.cancel();if(active)state.stops++;if(state.stops>=3){state.voice=false;const cb=$('#voice-toggle');if(cb)cb.checked=false;toast(L('Озвучивание отключено после трёх остановок. Его можно включить в настройках.','Үш рет тоқтатқан соң дыбыстау өшті. Баптауларда қайта қосуға болады.','Voice disabled after three interruptions. Re-enable it in settings.'));}}}
function showSources(){modal(L('Данные и иллюстрации','Деректер мен иллюстрациялар','Data and illustrations'),`<p>${L('Это самостоятельный frontend-прототип для HackAlem, не действующий магазин ekt.kz. Все товары, цены, остатки, отзывы, страны происхождения и даты поставок в демонстрации синтетические. Доступна отдельная датированная выборка API ekt.kz. LLM не подключена: ответы формируются сценарной логикой.','Бұл HackAlem үшін жеке frontend-прототип, ekt.kz нақты дүкені емес. Барлық тауарлар, бағалар, қор, пікірлер, шыққан елдер мен жеткізу күндері жасанды. ekt.kz API-інің жеке даталанған іріктемесі бар. LLM қосылмаған: жауаптар сценарий бойынша құрылады.','This is an independent HackAlem frontend prototype, not the live ekt.kz store. Products, prices, stock, reviews, origins and delivery dates are synthetic. A separate dated ekt.kz API sample is available. No LLM is connected; responses use scripted logic.')}</p><p>${L('Фото показывают только категорию: модель и бренд на изображении могут отличаться.','Фото тек санатты көрсетеді: суреттегі модель мен бренд өзгеше болуы мүмкін.','Photos illustrate categories only; pictured models and brands may differ.')}</p><p><a href="https://www.ato.com/16a-1-pole-5ka-miniature-circuit-breaker" target="_blank" rel="noreferrer">ATO — NB8-40J (catalog photo)</a><br><a href="https://commons.wikimedia.org/wiki/File:Schuko_socket.JPG" target="_blank" rel="noreferrer">Schuko socket — Dmitry G, Public Domain</a><br><a href="https://www.downlightsdirect.co.uk/integral-e27-dimmable-4000k-gls-bulbs.html" target="_blank" rel="noreferrer">Downlights Direct — Integral LED (catalog photo)</a><br><a href="https://commons.wikimedia.org/wiki/File:NYM_cable_and_clones.JPG" target="_blank" rel="noreferrer">NYM cable and clones — BPK, CC0</a></p>`);}
function showDemo(){modal(L('Демо за 90 секунд','90 секундтық демо','90-second demo'),`<ol style="line-height:2;font-size:.94rem"><li>${L('Спросите: «автомат C16 до 3000».','«C16» деп сұраңыз.','Ask: “C16 under 3000”.')}</li><li>${L('Запросите аналог DEMO-103, который распродан.','Сатылып біткен DEMO-103 баламасын сұраңыз.','Ask for an alternative to sold-out DEMO-103.')}</li><li>${L('Сравните DEMO-101 и DEMO-102; нажмите «Что лучше сейчас?».','DEMO-101 және DEMO-102 салыстырып, «Қазір қайсысы тиімді?» басыңыз.','Compare DEMO-101 and DEMO-102, then ask what is best now.')}</li><li>${L('Выберите 2 штуки. До «Да, добавить» корзина пуста.','2 дана таңдаңыз. «Иә, қосу» дегенге дейін себет бос.','Select 2 pieces. The cart stays empty until “Yes, add”.')}</li><li>${L('Откройте корзину, отзывы и мобильный вид.','Себетті, пікірлерді және мобильді көріністі ашыңыз.','Open the cart, reviews and mobile layout.')}</li></ol><p class="muted">${L('Голос выключен по умолчанию. Живой каталог, LLM, распознавание вложений и checkout требуют backend-интеграции.','Дауыс әдепкіде өшірулі. Нақты каталог, LLM, тіркемелерді тану және checkout backend интеграциясын қажет етеді.','Voice is off by default. Live catalog, LLM, attachment parsing and checkout require backend integration.')}</p>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){case'chat-open':ensureChat();break;case'chat-close':stopVoice();state.chatOpen=false;render();break;case'category':state.category=id;state.all=false;render();break;case'more':state.all=!state.all;renderProducts();break;case'stage':stage(id);break;case'confirm':confirm();break;case'cancel':state.pending=null;renderChat();break;case'analogs':showAnalogs(id);break;case'detail':showDetail(id);break;case'reviews':showDetail(id,true);break;case'suggest':send(b.dataset.text);break;case'comparison':showComparison();break;case'compare-clear':state.compare=[];render();break;case'compare-toggle':if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<3)state.compare.push(id);else toast(L('Можно сравнить до трёх товаров.','Үш тауарға дейін салыстыруға болады.','Compare up to three products.'));render();break;case'recommend-compare':$('#compare-answer').innerHTML=`<div class="muted-box" style="margin-top:15px">${esc(recommend(state.compare.map(get)))}</div>`;break;case'cart':showCart();history.replaceState(null,'','#cart');break;case'cart-edit':editCart(id);break;case'checkout-demo':modal(L('Проверка корзины','Себетті тексеру','Cart review'),`<p>${L('Демонстрационная корзина готова к передаче в checkout после подключения API магазина. В этой версии заказ не создаётся.','Демо-себет дүкен API-і қосылған соң checkout-қа жіберуге дайын. Бұл нұсқада тапсырыс жасалмайды.','The demo cart is ready for checkout integration. This version does not create an order.')}</p><p class="muted">${L('Сервер должен заново проверить цену, остаток и разрешение клиента.','Сервер бағаны, қорды және клиент рұқсатын қайта тексеруі тиіс.','The server must revalidate prices, stock and customer consent.')}</p><button class="primary" data-action="cart">${L('Вернуться в корзину','Себетке оралу','Back to cart')}</button>`);break;case'settings':showSettings();break;case'modal-close':closeModal();break;case'speak':speak(state.messages[Number(b.dataset.index)].text);break;case'voice-preview':speak(L('Здравствуйте! Помогу спокойно сравнить товары и выбрать подходящий вариант.','Сәлеметсіз бе! Тауарларды салыстырып, қолайлы нұсқаны таңдауға көмектесемін.','Hello! I can help you compare products and choose a suitable option.'));break;case'voice-stop':stopVoice();break;case'attach':$('#file-input').click();break;case'file-remove':state.file=null;renderAttachment();break;case'sources':showSources();break;case'demo':showDemo();break;}});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){state.query=e.target.value;state.all=true;renderProducts();}if(e.target.id==='pending-qty'&&state.pending){state.pending.qty=Number(e.target.value);$('#qty-summary').textContent=e.target.value;$('#pending-total').textContent=money(get(state.pending.id).price*(Number(e.target.value)||0));}});
function setLang(value){state.lang=value;saveStore('ekt-lang',value);stopVoice();state.voice=false;render();}
document.addEventListener('change',e=>{const el=e.target;if(el.id==='lang')setLang(el.value);if(el.id==='settings-lang'){setLang(el.value);showSettings();}if(el.id==='tone')state.tone=el.value;if(el.id==='voice-select')state.voiceURI=el.value;if(el.id==='voice-toggle'){state.voice=el.checked;if(el.checked){state.stops=0;if(!localVoices().length){state.voice=false;el.checked=false;toast(L('Локальный голос для этого языка недоступен.','Бұл тілге жергілікті дауыс жоқ.','No local voice for this language.'));}}else stopVoice();}if(el.id==='file-input'){const f=el.files[0];if(!f)return;if(!/\.(xlsx?|docx?|pdf|jpe?g)$/i.test(f.name)||f.size>10*1024*1024){toast(L('Допустимы Excel, Word, PDF, JPEG до 10 МБ.','10 МБ дейін Excel, Word, PDF, JPEG қабылданады.','Use Excel, Word, PDF or JPEG up to 10 MB.'));el.value='';return;}state.file={name:f.name,size:f.size};renderAttachment();}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();const input=$('#chat-input');const text=input.value;input.value='';send(text);}if(e.target.id==='review-form'){e.preventDefault();const p=get(e.target.dataset.id);const form=new FormData(e.target);const text=String(form.get('review')).trim(),score=Number(form.get('score'));if(text.length<5||text.length>1000||!Number.isInteger(score)||score<1||score>5)return;p.reviews.unshift({score,date:day(),author:L('Вы','Сіз','You'),text,synthetic:false});showDetail(p.id,true);renderProducts();toast(L('Отзыв добавлен только в демо-сессию.','Пікір тек демо-сессияға қосылды.','Review added to this demo session only.'));}if(e.target.id==='cart-edit-form'){e.preventDefault();const p=get(e.target.dataset.id),q=Number(new FormData(e.target).get('quantity'));if(!Number.isInteger(q)||q<0||q>p.stock){toast(L('Проверьте количество.','Санын тексеріңіз.','Check quantity.'));return;}if(q===0)delete state.cart[p.id];else state.cart[p.id]=q;saveStore('ekt-cart',state.cart);render();showCart();}});
let supplierCache=null;
async function showSupplier(selectedId){modal(L('Каталог ekt.kz','ekt.kz каталогы','ekt.kz catalog'),`<p>${L('Загрузка сохранённой выборки…','Сақталған іріктеме жүктелуде…','Loading saved sample…')}</p>`);try{supplierCache??=await fetch('./supplier-catalog.json').then(r=>{if(!r.ok)throw Error('snapshot unavailable');return r.json();});const s=supplierCache;const selected=selectedId?s.items.find(p=>p.id===Number(selectedId)):null;const retrieved=new Date(s.retrievedAt).toLocaleString({ru:'ru-RU',kk:'kk-KZ',en:'en-GB'}[state.lang]);modal(L('Каталог ekt.kz · данные API','ekt.kz каталогы · API деректері','ekt.kz catalog · API data'),`<div class="notice">${L('Снимок API от ','API суреттемесі: ','API snapshot captured ')}${esc(retrieved)}. ${L('Цена и наличие могли измениться. Реальная корзина не подключена.','Баға мен қор өзгеруі мүмкін. Нақты себет қосылмаған.','Prices and availability may have changed. Live cart is not connected.')}</div>${selected?`<p><button data-supplier="all">← ${L('К выборке','Іріктемеге оралу','Back to sample')}</button></p><div class="detail-top">${selected.image?`<img class="detail-image" src="${selected.image}" alt="${esc(selected.name)}">`:`<div class="muted-box">${L('Фото отсутствует в API','API-де фото жоқ','No photo in the API')}</div>`}<div><span class="badge">${esc(selected.article)}</span><h3>${esc(selected.name)}</h3><div class="price-large">${money(selected.price)}</div><p>${L('Остаток в снимке: ','Суреттемедегі қор: ','Snapshot stock: ')}${selected.quantity}</p><a href="${esc(selected.url)}" target="_blank" rel="noreferrer">${L('Карточка на ekt.kz','ekt.kz тауар карточкасы','View on ekt.kz')} ↗</a></div></div>${selected.warning?`<div class="notice">${L('Есть расхождение в данных: название и описание указывают 40 А, поле номинального тока — 125 А. Подбор аналога заблокирован до уточнения поставщиком.','Деректерде қайшылық бар: атауы мен сипаттамасында 40 А, номиналды ток өрісінде 125 А. Жеткізуші нақтылағанша балама таңдалмайды.','Conflicting data: name and description say 40 A, the rated current field says 125 A. Alternative selection is blocked until the supplier clarifies.')}</div>`:''}<h3>${L('Характеристики из API','API сипаттамалары','API specifications')}</h3><div class="specs">${Object.entries(selected.properties).map(([k,v])=>row(({TORGOVAYA_MARKA:L('Бренд','Бренд','Brand'),KOLICHESTVO_POLYUSOV:L('Полюсов','Полюстер','Poles'),NOMINALNYY_TOK:L('Номинальный ток','Номиналды ток','Rated current'),NOMINALNOE_NAPRYAZHENIE:L('Напряжение','Кернеу','Voltage'),NOMINALNAYA_OTKLYUCHAYUSHCHAYA_SPOSOBNOST:L('Отключающая способность','Ажырату қабілеті','Breaking capacity'),KRATNOST_MIN:L('Минимальная кратность','Ең аз еселік','Minimum multiple')})[k]||k,v)).join('')}</div><p style="white-space:pre-line">${esc(selected.description||L('Описание отсутствует.','Сипаттама жоқ.','No description.'))}</p><h3>${L('Остатки по складам','Қоймалардағы қор','Warehouse stock')}</h3>${selected.stores.length?selected.stores.map(st=>row(st.name,st.quantity)).join(''):`<p>${L('Нет в наличии. Дата поставки не предоставлена.','Қоймада жоқ. Жеткізу күні берілмеген.','Out of stock. No arrival date provided.')}</p>`}<p class="muted">${L('Отзывы, история цен, дата изготовления, сертификат и прогноз поставки в этой выборке не предоставлены.','Бұл іріктемеде пікірлер, баға тарихы, өндірілген күні, сертификат пен келу болжамы берілмеген.','Reviews, price history, manufacture date, certification and arrival forecasts are not provided in this sample.')}</p>`:`<p class="muted">${L('Реальные товары из тестового API. Исходные названия и описания сохранены на русском.','Тест API-дегі нақты тауарлар. Бастапқы атаулар мен сипаттамалар орыс тілінде сақталды.','Real products from the test API. Original names and descriptions remain in Russian.')}</p><div class="product-grid">${s.items.map(p=>`<article class="product"><div class="product-art">${p.image?`<img src="${p.image}" alt="${esc(p.name)}">`:`<span class="muted">${L('Фото не предоставлено','Фото берілмеген','No photo provided')}</span>`}</div><small>${esc(p.article)}</small><h3>${esc(p.name)}</h3><p>${L('Остаток в снимке','Суреттемедегі қор','Snapshot stock')}: ${p.quantity}</p><div class="product-bottom"><b>${money(p.price)}</b><button class="primary" data-supplier="${p.id}">${L('Подробнее','Толығырақ','Details')}</button></div></article>`).join('')}</div>`}`);}catch{modal(L('Каталог ekt.kz','ekt.kz каталогы','ekt.kz catalog'),`<p>${L('Не удалось загрузить выборку. Проверьте соединение и повторите.','Іріктеме жүктелмеді. Байланысты тексеріп, қайталаңыз.','Could not load the sample. Check your connection and retry.')}</p><button data-supplier="all">${L('Повторить','Қайталау','Retry')}</button>`);}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-supplier]');if(b)showSupplier(b.dataset.supplier==='all'?null:b.dataset.supplier);});
addEventListener('hashchange',()=>{if(location.hash==='#cart')showCart();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&'speechSynthesis'in window)speechSynthesis.cancel();});
render();if(location.hash==='#cart')showCart();
// Agent tools can inspect or prepare a proposal; only the visible confirmation mutates the cart.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_demo_catalog',title:'Read demo catalog',description:'Read synthetic demo products and their availability. Does not modify the cart.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:async(input)=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='query')||(input.query!==undefined&&(typeof input.query!=='string'||input.query.length>200)))throw Error('invalid_input');return (input.query?findProducts(input.query,products):products).map(p=>({id:p.id,name:name(p),price:p.price,stock:p.stock,source:'synthetic'}));}},{name:'stage_demo_cart_addition',title:'Prepare a demo cart addition',description:'Opens a visible proposal for the customer to confirm. Does not add products or submit an order.',inputSchema:{type:'object',properties:{id:{type:'string'},quantity:{type:'integer',minimum:1}},required:['id','quantity'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async(input)=>{if(!input||Object.keys(input).some(k=>!['id','quantity'].includes(k))||!get(input.id)||!Number.isInteger(input.quantity)||input.quantity<1)throw Error('invalid_input');const ok=stage(input.id,input.quantity);if(!ok)throw Error('insufficient_stock');return{status:'awaiting_visible_confirmation',id:input.id,quantity:input.quantity,cartCount:count()};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
